%[text] # Visually inspect plotElevationAndRoadGradeProfiles
Road.BaseHorizontalDistance = simscape.Value([0 50 100, 150 200 250, 400 450 500], "m");
Road.BaseGradePercent = [0 0 0, 2 2 2, 0 0 0];
Road.LeftElevation = simscape.Value(0, "m");

refined_data = buildElevationAndRoadGradeTable( ...
  BaseHorizontalDistance = Road.BaseHorizontalDistance, ...
  BaseGradePercent = Road.BaseGradePercent, ...
  InterpolationMethod = "smooth", ...
  InterpolationInterval = simscape.Value(0.1, "m"), ...
  LeftElevation = Road.LeftElevation );

% !inspection-target
fig = plotElevationAndRoadGradeProfiles( ... %[output:950d57e8]
  DataSource = "direct", ... %[output:950d57e8]
  BaseHorizontalDistance = Road.BaseHorizontalDistance, ... %[output:950d57e8]
  BaseGradePercent = Road.BaseGradePercent, ... %[output:950d57e8]
  RefinedHorizontalDistance = transpose(refined_data.HorizontalDistance), ... %[output:950d57e8]
  RefinedGradePercent = refined_data.GradePercent, ... %[output:950d57e8]
  RefinedElevation = transpose(refined_data.Elevation) ); %[output:950d57e8]

fig.Position(3:4) = [800, 300];  % width, height %[output:950d57e8]
